head.script:
scwin.gEmpNo;
scwin.gAcptNo; // 접수번호
scwin.gProcStat; // 처리단계
scwin.gProcTpText; // 보류 또는 유보 구분텍스트
scwin.gLdMktTpCd; // 상장공시시장구분
scwin.gDoc_LdMktTp;
scwin.gStatTitle;
scwin.gRscCd1;
scwin.gGetRsnCd1;
scwin.gDRsnCd2;
scwin.gListFormYn;
scwin.gIsurCd;
scwin.gGduty;
scwin.gEmpNo = js_emp_no; // 세션정보
scwin.gLdMktTpCd = js_market; // 로그인사용자의 시장구분
scwin.gGduty = js_gduty;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.libRoundPanel.PanelToGroupBox(pnl_1);
        await scwin.setCode();
        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_ReservInfo",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_ReservInfo=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        cmb_ReservRsn_2.setDisabled(true);
        // showObj(txb_rediscls_acptno, false);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10005.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_procs_stat_OnLoadCompleted
 * @description dts_procs_stat 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_procs_stat_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name dts_procs_stat_OnLoadError
 * @description dts_procs_stat 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_procs_stat_OnLoadError = async function() {
    try {
        await $c.win.alert('dts_procs_stat.OnLoadError()' + dts_procs_stat.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10005.dts_procs_stat_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Cancle_onclick
 * @description 「취소」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cancle_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10005.btn_Cancle_onclick" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.modifyReserv();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10005.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name trs_Reserv_OnSuccess
 * @description Reserv On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Reserv_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 " + scwin.gStatTitle + "처리 되었습니다.");

        // 부모창 reload 처리해야함
        // frame.Provider("../../frame_head").fn_HeadRead() ;
        $c.frame.path("../../frame_head").fn_CloseParentReload();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10005.trs_Reserv_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Reserv_OnFail
 * @description Reserv On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Reserv_OnFail = async function() {
    try {
        await $c.win.alert('trs_Reserv.OnFail() :' + trs_Reserv.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10005.trs_Reserv_OnFail" });
    }
};

/**
 * @method
 * @name dts_ReservRsn_OnLoadCompleted
 * @description dts_ReservRsn 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ReservRsn_OnLoadCompleted = async function(rowcount) {
    try {
        // 데이터셋 복사
        $c.stf.copyDataSet(dts_ReservRsn, dts_ReservRsn1);
        $c.stf.copyDataSet(dts_ReservRsn, dts_ReservRsn2);
        dts_ReservRsn1.UseFilter = true;
        dts_ReservRsn1.Filter();
        if (scwin.gProcStat === '20') {
            // 검토와 보류일떄
            // 담당자가 입력한 보류내용을 읽어오기
            const sbmOptions = {
                id : "sbm_dts_ReservRead",
                action : "/DisclosureStatus.do",
                ref : "",
                target : "dts_ReservRead=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10005.dts_ReservRsn_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ReservRsn2_OnLoadCompleted
 * @description dts_ReservRsn2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ReservRsn2_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name dts_ReservRsn1_OnFilter
 * @description Reserv Rsn1 On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_ReservRsn1_OnFilter = function(row) {
    try {
        if (dts_ReservRsn1.getCellData(row, "value").length === 2) {
            return true;
        } else {
            return false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10005.dts_ReservRsn1_OnFilter" });
    }
};

/**
 * @method
 * @name cmb_ReservRsn_1_onselchange2
 * @description cmb Reserv Rsn 1 onselchange2 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_ReservRsn_1_onselchange2 = function() {
    try {
        scwin.gRscCd1 = $c.cp.valueOfIndex(cmb_ReservRsn_1, "value", cmb_ReservRsn_1.getSelectedIndex());
        dts_ReservRsn2.UseFilter = true;
        dts_ReservRsn2.Filter();

        // 유보사유 중분류 선택할 값이 있으면 enable
        if (dts_ReservRsn2.getRowCount() > 0) {
            cmb_ReservRsn_2.setDisabled(false);
            cmb_ReservRsn_2.trigger("onclick");
        } else {
            cmb_ReservRsn_2.setDisabled(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10005.cmb_ReservRsn_1_onselchange2" });
    }
};

/**
 * @method
 * @name cmb_ReservRsn_1_OnSelected
 * @description cmb Reserv Rsn 1 On Selected 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_ReservRsn_1_OnSelected = function() {

};

/**
 * @method
 * @name dts_ReservRsn2_OnFilter
 * @description Reserv Rsn2 On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_ReservRsn2_OnFilter = function(row) {
    try {
        //  대분류에 해당하는 중분류를 가져온다.
        if (dts_ReservRsn2.getCellData(row, "value").substr(0, 2) === scwin.gRscCd1 &&
            dts_ReservRsn2.getCellData(row, "value").length === 4) {
            return true;
        } else {
            return false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10005.dts_ReservRsn2_OnFilter" });
    }
};

/**
 * @method
 * @name dts_ReservRead_OnLoadCompleted
 * @description dts_ReservRead 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ReservRead_OnLoadCompleted = function(rowcount) {
    try {
        scwin.gRscCd1 = dts_ReservRead.getCellData(1, "RESERV_RSN_CD1");
        dts_ReservRsn2.UseFilter = true;
        dts_ReservRsn2.Filter();
        scwin.gDRsnCd2 = dts_ReservRead.getCellData(1, "RESERV_RSN_CD2");
        if (scwin.gDRsnCd2 === null || scwin.gDRsnCd2 === '') {
            cmb_ReservRsn_2.setDisabled(true);
        } else {
            cmb_ReservRsn_2.setValue(scwin.gDRsnCd2);
            cmb_ReservRsn_2.setDisabled(false);
        }
        rdo_rediscls_yn.setValue(dts_ReservRead.getCellData(1, "REDISCLS_YN"));
        /*
        setObjectValue(txb_rediscls_acptno, dts_ReservRead.NameValue(1,"REDISCLS_ACPT_NO")) ;
        setObjectValue(txb_acpt_ddtm, dts_ReservRead.NameValue(1,"REDISCLS_DOC_TITLE")) ;
        setObjectValue(txb_doc_title, dts_ReservRead.NameValue(1,"REDISCLS_PROCS_DDTM")) ;
         */
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10005.dts_ReservRead_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ReservTp_OnLoadCompleted
 * @description dts_ReservTp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ReservTp_OnLoadCompleted = function(rowcount) {
    try {
        // 유가일때 디폴트는 정정유보
        if (scwin.gDoc_LdMktTp === '1') {
            cmb_ReservTp.setValue('2');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10005.dts_ReservTp_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name rdo_rediscls_yn_onselchange
 * @description rdo_rediscls_yn onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_rediscls_yn_onselchange = function() {
    /*
    	if (rdo_rediscls_yn.CodeValue == 2) {
    		setObjectValue(txb_acpt_ddtm, "");
    		setObjectValue(txb_doc_title, "");
    		setObjectValue(txb_rediscls_acptno, "");
    	}
     */
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 코드 셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    let vLdMktTpCd;

    // 공시유보유형 리스트  셋팅
    const sbmOptions = {
        id : "sbm_dts_ReservTp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ReservTp=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (scwin.gDoc_LdMktTp === '3') {
        // 선물시장일땐 코스닥기준으로 가져온다.
        vLdMktTpCd = '2';
    } else {
        vLdMktTpCd = scwin.gLdMktTpCd;
    }
    if (scwin.gGduty === '11') {
        vLdMktTpCd = '1';
    }

    // 공시유보사유 리스트 셋팅
    const sbmOptions2 = {
        id : "sbm_dts_ReservRsn",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ReservRsn=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 부모창의 데이타 셋팅하기
    scwin.setParamData();
};

/**
 * @method
 * @name getProcsSate
 * @description 처리상태 조회하기
 * @param {*} gAcptNo gAcptNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getProcsSate = async function(gAcptNo) {
    const sbmOptions = {
        id : "sbm_dts_procs_stat",
        action : "/Viewer.do",
        ref : "",
        target : "dts_procs_stat=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const vPROCS_STAT_CD = dts_procs_stat.getCellData(1, "PROCS_STAT_CD");
    const vPROCS_STAT_NM = dts_procs_stat.getCellData(1, "PROCS_STAT_NM");
    const vPROCS_DDTM = dts_procs_stat.getCellData(1, "PROCS_DDTM");
    if (scwin.gProcStat !== vPROCS_STAT_CD) {
        await $c.win.alert("본 공시가 " + vPROCS_DDTM + "에  이미 [" + vPROCS_STAT_NM + "] 처리가 되었습니다.");
        // fn_CloseParentReload();
        return false;
    } else {
        return true;
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParamData
 * @description 부모창의 데이타 셋팅하기
 * @returns {void}
 * @hidden N
 */
scwin.setParamData = function() {
    /*
    gAcptNo = frame.Provider("../../frame_head").dts_AcptProcs.NameString(1, 'ACPT_NO');
    gProcStat =frame.Provider("../../frame_head").dts_AcptProcs.NameString(1, 'PROCS_STAT_CD');	// 현재 문서의 처리상태
    gDoc_LdMktTp =frame.Provider("../../frame_head").dts_AcptProcs.NameString(1, 'LD_MKT_TP_CD');
     */
    scwin.gAcptNo = $c.frame.path("../../frame_head").scwin.gAcptNo;
    scwin.gIsurCd = $c.frame.path("../../frame_head").scwin.gIsurCd;
    scwin.gProcStat = $c.frame.path("../../frame_head").gProcsStatCd;
    scwin.gDoc_LdMktTp = $c.frame.path("../../frame_head").scwin.gDoc_LdMktTp;
    scwin.gListFormYn = $c.frame.path("../../frame_head").scwin.gListFormYn;
    gComAbbrv = $c.frame.path("../../frame_head").scwin.gListFormYn;

    // alert('gDoc_LdMktTp'+gDoc_LdMktTp);
    if (scwin.gListFormYn === 'Y') {
        // 상장서식이면 보류단계 없음
        /*
        cmb_ReservRsn_1.Enable2 = false;
        cmb_ReservTp.Enable2 = true;
        showObj(label_noti, false);
         */
        scwin.gStatTitle = "유보";
        // 코스닥일 경우는 선택 불가
        if (scwin.gDoc_LdMktTp === '2' || scwin.gDoc_LdMktTp === '6') {
            cmb_ReservTp.setDisabled(true);
            label_stk.hide();
            label_kos.show("");
            label_noti.show("");
            pnl_rediscl.show("");
        } else {
            cmb_ReservTp.setDisabled(false);
            label_stk.show("");
            label_kos.hide();
            label_noti.hide();
            pnl_rediscl.hide();
            txa_ReservRsnContn.height = "184";
        }
    } else {
        // 코스닥일 경우는 선택 불가
        if (scwin.gDoc_LdMktTp === '2' || scwin.gDoc_LdMktTp === '6') {
            cmb_ReservTp.setDisabled(true);
            label_stk.hide();
            label_kos.show("");
            label_noti.show("");
            pnl_rediscl.show("");
        } else {
            cmb_ReservTp.setDisabled(false);
            label_stk.show("");
            label_kos.hide();
            label_noti.hide();
            pnl_rediscl.hide();
            txa_ReservRsnContn.height = "184";
        }
        if (scwin.gProcStat === '00' || scwin.gProcStat === '01' || scwin.gProcStat === '02') {
            // 미처리와 재검토요구일떄
            scwin.gStatTitle = "보류";
        } else if (scwin.gProcStat === '10' || scwin.gProcStat === '20' || scwin.gProcStat === '15') {
            // 검토와 보류일떄
            scwin.gStatTitle = "유보";
            /*
            // 담당자가 입력한 보류내용을 읽어오기
            var url = "/DisclosureStatus.do?method=readDisclosureReserve&inputMessageId=DSCLRESERVELIST_OUT"
            		+ "&outputMessageId=DSCLRESERVELIST_OUT"
            		+ "&ACPT_NO=" +gAcptNo
            		+ "&DISCLS_PROCS_TP_CD=20";

            dts_ReservRead.DataID = encodeURI(url);
            dts_ReservRead.reset();
             */

        } else {
            scwin.gStatTitle = "유보";
        }
    }
};

/**
 * @method
 * @name modifyReserv
 * @description 보류처리하기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modifyReserv = async function() {
    const vTp = cmb_ReservTp.getValue();
    if (scwin.gLdMktTpCd === 1 && vTp.length < 1) {
        await $c.win.alert("유보 유형을 선택하시오.");
        cmb_ReservTp.focus();
        return;
    }

    // 유보사유코드 셋팅
    let vRsnCd1 = '';
    let vRsnCd2 = '';
    let vRsnCd = '';
    if (scwin.gListFormYn !== 'Y') {
        // 상장서식이면 보류단계 없음
        vRsnCd1 = cmb_ReservRsn_1.getValue();
        vRsnCd2 = cmb_ReservRsn_2.getValue();
        if (vRsnCd1.length < 1) {
            await $c.win.alert("유보 사유유형을 선택하시오.");
            cmb_ReservRsn_1.focus();
            return;
        }
        if (scwin.gDoc_LdMktTp === '1') {
            // 유가일때
            if (vRsnCd1 === '02' && vRsnCd2.length < 1) {
                await $c.win.alert("유보 사유 유형의 중분류 선택하시오.");
                cmb_ReservRsn_2.focus();
                return;
            }
        } else {
            if (vRsnCd1 === '03' && vRsnCd2.length < 1) {
                await $c.win.alert("유보 사유 유형의 중분류 선택하시오.");
                cmb_ReservRsn_2.focus();
                return;
            }
        }

        /*
        if(dts_ReservRsn2.CountRow  > 0 && vRsnCd2.length < 1) {
        	alert("유보 사유 유형의 중분류 선택하시오." );
        	cmb_ReservRsn_2.focus();
        	return;
        }
         */
        // alert(vRsnCd1 +" = "+vRsnCd2);

        if (vRsnCd2.length === 4) {
            vRsnCd = vRsnCd2;
        } else {
            vRsnCd = vRsnCd1;
        }
    }
    const vRsnContn = txa_ReservRsnContn.getValue();
    /*  // 선택사항이므로 체크안함.
    if(vRsnContn.length < 1) {
    	alert("유보 사유를 입력하시오." );
    	txa_ReservRsnContn.focus();
    	return;

    }
     */

    if ($c.stf.checkMaxLength(txa_ReservRsnContn, 500, '유보사유') === false) {
        return;
    }
    let vRedisclsYn;
    if (rdo_rediscls_yn.getValue() === '1') {
        vRedisclsYn = 'Y';
    } else {
        vRedisclsYn = 'N';
    }
    // 코스닥일 경우만 체크  : 사후에 입력하므로 체크로직 삭제
    /*
    if( gDoc_LdMktTp == '2') {
    	if ( vRedisclsYn  == 'Y' && getObjectValue(txb_rediscls_acptno) == "") {
    		alert("재공시유무에 '예'를 선택하셨을 경우에는 반드시 재공시를 선택하셔야 합니다.");
    		return false;
    	}

    	if ( vRedisclsYn  == 'N' && getObjectValue(txb_rediscls_acptno) != "") {
    		alert("재공시를 선택하셨을 경우에는 재공시유무에 '예'를 선택하셔야 합니다.");
    		rdo_rediscls_yn.focus();
    		return false;
    	}

    }
     */

    if (scwin.gAcptNo === '') {
        await $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    dts_ReservInfo.insertRow();
    dts_ReservInfo.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_ReservInfo.setCellData(1, "LDMKTTP_CD", scwin.gLdMktTpCd);
    dts_ReservInfo.setCellData(1, "RESERV_TP_CD", vTp);
    dts_ReservInfo.setCellData(1, "DISCLS_RESERV_RSN_CD", vRsnCd);
    dts_ReservInfo.setCellData(1, "DISCLS_PROCS_RSN_DTL_CONTN", vRsnContn);
    dts_ReservInfo.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_ReservInfo.setCellData(1, "REDISCLS_YN", vRedisclsYn);
    // dts_ReservInfo.NameValue(1,"REDISCLS_ACPT_NO") = getObjectValue(txb_rediscls_acptno);
    dts_ReservInfo.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    if (dts_ReservInfo.getCellData(1, "ACPT_NO") === '') {
        await $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    const vAnswer = confirm(scwin.gStatTitle + '처리 하시겠습니까?');
    if (vAnswer === true) {
        if (await scwin.getProcsSate(scwin.gAcptNo) === false) {
            await scwin.closeParentReload();
            return false;
        } else {
            let url = '';
            if (scwin.gListFormYn === 'Y') {
                // 상장서식이면 보류단계 없음
                url = "/DisclosureApproval.do?method=processDisclosureReserve&inputMessageId=RESERVRSN_INOUT";
            } else {
                if (scwin.gProcStat === '00' || scwin.gProcStat === '01' || scwin.gProcStat === '02') {
                    // 미처리와 재검토요구일떄 -> 보류
                    url = "/DisclosureStudy.do?method=processDisclosureHold&inputMessageId=RESERVRSN_INOUT";
                } else if (scwin.gProcStat === '10' || scwin.gProcStat === '20' || scwin.gProcStat === '15') {
                    // 검토와 보류일떄 -> 유보
                    url = "/DisclosureApproval.do?method=processDisclosureReserve&inputMessageId=RESERVRSN_INOUT";
                } else {
                    url = "/DisclosureApproval.do?method=processDisclosureReserve&inputMessageId=RESERVRSN_INOUT";
                }
            }
            trs_Reserv.Action = url + "&SCREN_ID=" + 'ULDSTF10005.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&ACPT_NO=" + scwin.gAcptNo;
            trs_Reserv.KeyName = "toinb_dataid4";
            trs_Reserv.KeyValue = "JSP(I:pInput=dts_ReservInfo)";
            trs_Reserv.Post();
        }
    }
};

/**
 * @method
 * @name closeParentReload
 * @description 뷰어 닫고,  검색목록 reload
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.closeParentReload = async function() {
    // 화면닫기
    $c.frame.path("../../frame_head").fn_CloseParentReload();
    await $c.win.closePopup();
};
